-- pronoun-fix-batch1: copy rewritten without pronouns the sources do not state. Guarded on the current English description.
begin;

update public.businesses set description_en = $tx$Joseph Lau is a State Farm insurance agent with an office at 4080 W Ray Rd, Suite 20, in Chandler. The agency offers auto, motorcycle, homeowners, condo, renters, life and small business insurance, along with Medicare supplement and supplemental health plans, pet insurance, and U.S. Bank banking products offered through State Farm. The office serves customers in English, Mandarin, Cantonese and Taiwanese, and appointments are available on weekends and after hours.$tx$,
  description_zh_tw = $tx$Joseph Lau 是 State Farm 保險代理人，辦公室位於錢德勒（Chandler）4080 W Ray Rd, Suite 20。代理處提供汽車、機車、房屋、公寓、租屋、人壽及小型企業保險，也有聯邦醫療保險補充計畫（Medicare Supplement）、補充健康保險、寵物保險，以及透過 State Farm 合作提供的 U.S. Bank 銀行產品。辦公室可用英語、國語、粵語及台語服務，週末及下班後也可預約。$tx$,
  short_description_en = $tx$State Farm agent in Chandler offering auto, home, life and business insurance in English, Mandarin, Cantonese and Taiwanese.$tx$,
  short_description_zh_tw = $tx$錢德勒 State Farm 保險代理人，提供汽車、房屋、人壽及商業保險，可說英語、國語、粵語及台語。$tx$,
  last_updated = now()
where slug = 'joseph-lau-state-farm-chandler' and description_en = $tx$Joseph Lau is a State Farm insurance agent with an office at 4080 W Ray Rd, Suite 20, in Chandler. His agency offers auto, motorcycle, homeowners, condo, renters, life and small business insurance, along with Medicare supplement and supplemental health plans, pet insurance, and U.S. Bank banking products offered through State Farm. The office serves customers in English, Mandarin, Cantonese and Taiwanese, and appointments are available on weekends and after hours.$tx$;

update public.businesses set description_en = $tx$Katie Lau is a State Farm insurance agent with an office at 1245 W Guadalupe Rd, Suite B4, in Mesa. Born and raised in Hong Kong, Katie Lau moved to the United States in 2003 and worked up from bank teller to senior branch manager before becoming an agent; the agency's site cites more than 22 years of experience in finance and insurance. The agency handles home, auto, commercial, life and health insurance, and offers service in English, Cantonese, Mandarin and Vietnamese. After-hours appointments are available.$tx$,
  description_zh_tw = $tx$Katie Lau 是 State Farm 保險代理人，辦公室位於梅薩（Mesa）1245 W Guadalupe Rd, Suite B4。Katie Lau 在香港出生長大，2003 年移民美國，從銀行櫃員一路做到資深分行經理，之後轉任保險代理人；網站表示其在金融與保險業已有超過 22 年經驗。代理處承辦房屋、汽車、商業、人壽及健康保險，可用英語、粵語、國語及越南語服務，下班後也可預約。$tx$,
  short_description_en = $tx$Hong Kong-born State Farm agent in Mesa offering home, auto, business, life and health insurance in English, Cantonese and Mandarin.$tx$,
  short_description_zh_tw = $tx$在香港出生的梅薩 State Farm 保險代理人，提供房屋、汽車、商業、人壽及健康保險，可說英語、粵語及國語。$tx$,
  last_updated = now()
where slug = 'katie-lau-state-farm-mesa' and description_en = $tx$Katie Lau is a State Farm insurance agent with an office at 1245 W Guadalupe Rd, Suite B4, in Mesa. Born and raised in Hong Kong, she moved to the United States in 2003 and worked her way from bank teller to senior branch manager before becoming an agent; her site cites more than 22 years of experience in finance and insurance. Her agency handles home, auto, commercial, life and health insurance, and she offers service in English, Cantonese, Mandarin and Vietnamese. After-hours appointments are available.$tx$;

update public.businesses set description_en = $tx$Tak Sun (孫維特) is a licensed insurance agent with Comparion Insurance Agency at 180 S Arizona Ave, Suite 102, in Chandler. Sun has worked as an insurance agent in Arizona for more than two decades and can quote options from more than 15 insurance carriers, covering car, home, umbrella, life and pet insurance. Born in Taiwan, Sun speaks Mandarin and Taiwanese as well as English, and the agent page includes a Chinese-language introduction. Sun is also licensed in California, Montana, New Mexico and Nevada.$tx$,
  description_zh_tw = $tx$孫維特（Tak Sun）是 Comparion Insurance Agency 的持照保險代理人，辦公室位於錢德勒 180 S Arizona Ave, Suite 102。孫維特在亞利桑那從事保險代理已超過二十年，可比較超過 15 家保險公司的方案，涵蓋汽車、房屋、傘式責任、人壽及寵物保險。孫維特在台灣出生，能以國語、台語及英語服務，代理人頁面也有中文自我介紹。另持有加州、蒙大拿州、新墨西哥州及內華達州的保險執照。$tx$,
  short_description_en = $tx$Taiwan-born insurance agent in Chandler comparing car, home, life and pet coverage from 15+ carriers; speaks Mandarin and Taiwanese.$tx$,
  short_description_zh_tw = $tx$在台灣出生的錢德勒保險代理人，比較超過 15 家保險公司的汽車、房屋、人壽及寵物保險，可說國語及台語。$tx$,
  last_updated = now()
where slug = 'tak-sun-comparion-insurance-chandler' and description_en = $tx$Tak Sun (孫維特) is a licensed insurance agent with Comparion Insurance Agency at 180 S Arizona Ave, Suite 102, in Chandler. He has worked as an insurance agent in Arizona for more than two decades and can quote options from more than 15 insurance carriers, covering car, home, umbrella, life and pet insurance. Born in Taiwan, he speaks Mandarin and Taiwanese as well as English, and his agent page includes a Chinese-language introduction. He is also licensed in California, Montana, New Mexico and Nevada.$tx$;

update public.businesses set description_en = $tx$Ling Zhu is a full-time Realtor with RE/MAX Signature, whose office is at 19820 N 7th St, Suite 110, in Phoenix. Ling Zhu helps home buyers and sellers across the Phoenix metro area, lists Surprise, Gilbert, Peoria, Glendale and Chandler among the service areas, and speaks English and Mandarin. The RE/MAX profile shows nine years of experience and specialties including first-time buyers, new construction, investment and retirement properties. Arizona license SA674361000.$tx$,
  description_zh_tw = $tx$Ling Zhu 是 RE/MAX Signature 的全職房地產經紀人，公司辦公室位於鳳凰城 19820 N 7th St, Suite 110。Ling Zhu 協助大鳳凰城地區的買家與賣家，服務範圍包括 Surprise、吉爾伯特、皮奧里亞、格倫代爾及錢德勒，可說英語及國語。RE/MAX 個人頁面顯示具九年經驗，專長包括首次購屋、新建案、投資及退休物業。亞利桑那執照號碼 SA674361000。$tx$,
  short_description_en = $tx$Full-time RE/MAX Signature Realtor serving buyers and sellers across the Phoenix metro in English and Mandarin.$tx$,
  short_description_zh_tw = $tx$RE/MAX Signature 全職房地產經紀人，以英語及國語服務大鳳凰城地區的買家與賣家。$tx$,
  last_updated = now()
where slug = 'ling-zhu-phoenix' and description_en = $tx$Ling Zhu is a full-time Realtor with RE/MAX Signature, whose office is at 19820 N 7th St, Suite 110, in Phoenix. She helps home buyers and sellers across the Phoenix metro area, lists Surprise, Gilbert, Peoria, Glendale and Chandler among her service areas, and speaks English and Mandarin. Her RE/MAX profile shows nine years of experience and specialties including first-time buyers, new construction, investment and retirement properties. Arizona license SA674361000.$tx$;

update public.businesses set description_en = $tx$Christy Crouse (劉純) is a Mandarin-speaking real estate associate with RE/MAX Fine Properties, whose office is at 21020 N Pima Rd in Scottsdale. A first-generation Chinese-American, Christy Crouse runs a Chinese-focused real estate website and works with buyers and sellers in Phoenix, Chandler, Gilbert, Mesa, Scottsdale and Tempe. The site says Crouse has sold hundreds of homes, and the RE/MAX profile lists 21 years of experience. Arizona license SA566516000.$tx$,
  description_zh_tw = $tx$劉純（Christy Crouse）是 RE/MAX Fine Properties 會說國語的房地產經紀人，公司辦公室位於斯科茨代爾 21020 N Pima Rd。劉純是第一代華裔美國人，經營以華人客戶為主的房地產網站，服務鳳凰城、錢德勒、吉爾伯特、梅薩、斯科茨代爾及坦佩的買家與賣家。網站表示其已售出數百棟房屋，RE/MAX 個人頁面顯示具 21 年經驗。亞利桑那執照號碼 SA566516000。$tx$,
  short_description_en = $tx$Mandarin-speaking RE/MAX Fine Properties associate serving Chinese-speaking buyers and sellers across the East Valley and Phoenix.$tx$,
  short_description_zh_tw = $tx$RE/MAX Fine Properties 會說國語的房地產經紀人，服務東谷及鳳凰城地區的華人買家與賣家。$tx$,
  last_updated = now()
where slug = 'christy-crouse-scottsdale' and description_en = $tx$Christy Crouse (劉純) is a Mandarin-speaking real estate associate with RE/MAX Fine Properties, whose office is at 21020 N Pima Rd in Scottsdale. A first-generation Chinese-American, she runs a Chinese-focused real estate website and works with buyers and sellers in Phoenix, Chandler, Gilbert, Mesa, Scottsdale and Tempe. Her site says she has sold hundreds of homes, and her RE/MAX profile lists 21 years of experience. Arizona license SA566516000.$tx$;

update public.businesses set description_en = $tx$Jean Woodland is an associate broker with Realty Executives Arizona Territory, working from its North Scottsdale office at 31307 N Scottsdale Rd. Jean Woodland speaks English, Mandarin and Cantonese and helps clients buy, sell and invest in real estate. Before real estate, Woodland spent years in admissions consulting and career counseling for international students, and more than a decade in international trade and business consulting, experience now applied to negotiating for clients.$tx$,
  description_zh_tw = $tx$Jean Woodland 是 Realty Executives Arizona Territory 的協理經紀人（Associate Broker），在公司位於 31307 N Scottsdale Rd 的北斯科茨代爾辦公室執業。Woodland 能說英語、國語及粵語，協助客戶買房、賣房及投資房地產。投身房地產前，Woodland 多年從事國際學生的升學顧問與職涯輔導，並有十多年國際貿易與商業顧問經驗，如今運用這些經驗為客戶談判。$tx$,
  short_description_en = $tx$North Scottsdale associate broker who helps clients buy, sell and invest in English, Mandarin and Cantonese.$tx$,
  short_description_zh_tw = $tx$北斯科茨代爾協理經紀人，以英語、國語及粵語協助客戶買房、賣房及投資。$tx$,
  last_updated = now()
where slug = 'jean-woodland-scottsdale' and description_en = $tx$Jean Woodland is an associate broker with Realty Executives Arizona Territory, working from its North Scottsdale office at 31307 N Scottsdale Rd. She speaks English, Mandarin and Cantonese and helps clients buy, sell and invest in real estate. Before real estate she spent years in admissions consulting and career counseling for international students, and more than a decade in international trade and business consulting, experience she now applies to negotiating for her clients.$tx$;

commit;
